import 'package:cloud_firestore/cloud_firestore.dart';
class OfflineSyncQueue { final FirebaseFirestore db; OfflineSyncQueue({FirebaseFirestore? firestore}):db=firestore??FirebaseFirestore.instance; Future<void> enqueue(String uid,String id,Map<String,dynamic> payload)=>db.collection('users').doc(uid).collection('syncQueue').doc(id).set({'payload':payload,'state':'pending','attempts':0,'createdAt':FieldValue.serverTimestamp()},SetOptions(merge:true)); Future<void> complete(String uid,String id)=>db.collection('users').doc(uid).collection('syncQueue').doc(id).set({'state':'done','completedAt':FieldValue.serverTimestamp()},SetOptions(merge:true)); }